// Run after stage4-natural: its input is generated by continuous new-save victories.
import fs from'node:fs';import assert from'node:assert/strict';import{World,recordVictory,canSelect}from'../web/domain.mjs';import{trainHeroSkill}from'../web/progression.mjs';import{buyUpgrade}from'../web/upgrades.mjs';import{playStage5}from'./stage5-strategy.mjs';
const read=p=>JSON.parse(fs.readFileSync('web/assets/'+p)),b=read('catalog.json'),e=read('expansion/catalog.json'),a=read('arcane/catalog.json'),blade=read('blade/catalog.json'),prior=JSON.parse(fs.readFileSync('artifacts/stage4-natural-results.json'));assert.equal(prior.ready,true);let save=structuredClone(prior.save);assert.equal(save.unlocked,5);assert.equal(save.stars[5],undefined);for(const key of['ultimate','porcupine','nimble_fencer']){const next=trainHeroSkill(save,key,b.templates.hero_elves_archer.hero.skills);if(next)save=next;}for(const key of['barrack_el_elven_fencing','barrack_el_expert_tactician'])buyUpgrade(save,key);const results=[];
for(const mode of['campaign','heroic','iron']){if(mode==='heroic')for(const key of['double_strike','porcupine','ultimate','nimble_fencer']){const next=trainHeroSkill(save,key,b.templates.hero_elves_archer.hero.skills);if(next)save=next;}assert.ok(canSelect(save,5,mode));const d={...read('expansion/05-'+mode+'.json'),templates:{...b.templates,...e.templates,...a.templates,...blade.templates},animations:b.animations},w=new World(d,{difficulty:1,heroXp:save.heroXp,heroSkills:save.heroSkills,upgrades:save.upgrades}),r=playStage5(w);console.log(JSON.stringify(r));assert.equal(r.status,'won',JSON.stringify(r));assert.equal(r.leaks,0);if(mode==='campaign')assert.equal(w.stars,3);results.push(r);save=recordVictory(save,w);}
assert.equal(save.unlocked,6);assert.equal(save.stars[5],3);assert.equal(save.challenges['5-heroic'],true);assert.equal(save.challenges['5-iron'],true);assert.equal(canSelect(save,6),true);fs.writeFileSync('artifacts/stage5-natural-results.json',JSON.stringify({scope:'continuous earned XP/stars from new-save stages1–4 then all stage5 modes; legal player API; no injected budget/HP/XP/unlocks; not original synchronized pixels',results,save,ready:true},null,2));
